{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE redtape_db.Maplemonk.redtape_db_Tata_margin_fact_items as SELECT COALESCE(B.EAN,REPLACE(REPLACE(A.EANUPC, \'`\', \'\'), \',\', \'\')) EAN, A.SKU, A.GENDER, UPPER(A.CATEGORY_NAME) CATEGORY_NAME, A.SAP_CATEGORY, UPPER(A.TYPE) TYPE, UPPER(A.LEVEL) LEVEL, A.FLIPKART_CATEGORY CATEGORY, AVAILABLE_QUANTITY, 74.0 AS \"DISCOUNT_%\", CASE WHEN RF.\"Courier Return %\" IS NULL OR RF.\"Courier Return %\" = 0 THEN 25 ELSE ROUND(RF.\"Courier Return %\",2) END AS \"COURIER_RET%\", CASE WHEN RF.\"Customer Return %\" IS NULL OR RF.\"Customer Return %\" = 0 THEN 11 ELSE ROUND(RF.\"Customer Return %\", 2)END AS \"CUSTOMER_RET%\", CAST(REPLACE(A.COST, \',\', \'\') AS FLOAT) AS COST, CAST(REPLACE(A.MRP, \',\', \'\') AS FLOAT) AS MRP, ROUND(COALESCE(MRP,0) / NULLIF(COST, 0),2) AS MULTIPLE, ROUND(COALESCE(MRP,0) - (COALESCE(MRP,0) * \"DISCOUNT_%\" / 100),2) AS BILL_VALUE, CASE WHEN BILL_VALUE < 2625 THEN 5 ELSE 18 END AS \"GST_%\", ROUND((BILL_VALUE * 100 / NULLIF(100 + \"GST_%\", 0)),2) AS SALE_VALUE, ROUND(COALESCE(COMMISSION,0),2) \"COMMISSION_%\", ROUND((COALESCE(BILL_VALUE,0) * COALESCE(\"COMMISSION_%\"/100,0)),2) AS COMMISSION_VALUE, ROUND(COALESCE(COALESCE(SALE_VALUE,0) - COALESCE(COST,0),0),2) AS GROSS_MARGIN, ROUND((GROSS_MARGIN/NULLIF(SALE_VALUE,0)*100),2) \"GROSS_MARGIN%\", 99.0 AS PROCESSSING_FEE, 0.0 AS PACKING, ROUND(BILL_VALUE *(2.25/100),2) ADVT, ROUND(SALE_VALUE *(7.5/100),2) COMMON, ROUND(COALESCE(COMMISSION_VALUE,0) +COALESCE(PROCESSSING_FEE,0) +COALESCE(PACKING,0) + COALESCE(ADVT,0) + COALESCE(COMMON,0),2) AS TOTAL_EXPENSES, ROUND(COALESCE((TOTAL_EXPENSES / NULLIF(SALE_VALUE,0)),0),2) AS \"EXPENSES%\", ROUND(COALESCE((GROSS_MARGIN - TOTAL_EXPENSES),0),2) AS NET_MARGIN, ROUND((NET_MARGIN/NULLIF(SALE_VALUE,0)*100),2) \"NET_MARGIN%\" FROM MAPLEMONK.REDTAPE_DB_MARGIN_PRODUCT_MASTER A LEFT JOIN ( SELECT * FROM ( SELECT \"Report Generated Date\"::DATE AS FIRST_DATE, REPLACE(EAN, \'`\', \'\') AS EAN, SUM(\"Available Quantity\") AS AVAILABLE_QUANTITY FROM REDTAPE_DB.MAPLEMONK.EASYECOM_REDTAPE_INVENTORY_SNAPSHOT WHERE \"Report Generated Date\" IS NOT NULL GROUP BY 1,2) QUALIFY ROW_NUMBER() OVER(PARTITION BY EAN ORDER BY FIRST_DATE DESC) = 1) B ON REPLACE(A.EANUPC, \'`\', \'\') = REPLACE(B.EAN, \'`\', \'\') LEFT JOIN( SELECT DISTINCT UPPER(SAP_CATEGORY) SAP_CATEGORY ,COMMISSION FROM MAPLEMONK.REDTAPE_TATA_MARGIN_COMMISSION )MC ON UPPER(TRIM(A.SAP_CATEGORY)) = UPPER(TRIM(MC.SAP_CATEGORY)) LEFT JOIN ( SELECT \"TYPE 2\" TYPE ,GENDER ,\"Courier Return %\" ,\"Customer Return %\" FROM MAPLEMONK.REDTAPE_TATA_MARGIN_RETURN_FOOTWEAR WHERE UPPER(GENDER) != \'ALL\') RF ON UPPER(TRIM(A.TYPE)) = UPPER(TRIM(RF.TYPE)) AND UPPER(TRIM(A.GENDER)) = UPPER(TRIM(RF.GENDER)) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from REDTAPE_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            